    <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="PreviousPage">Previous</button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNumber = i;
        <button class="btn-page @(pageNumber == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNumber))">
            @pageNumber
        </button>
    }

    <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="NextPage">Next</button>
